# area: dunder_dispatch
# hypothesis: len() and iter() look up __len__ and __iter__ on the type, so instance-assigned dunders and a class-level __getattr__ fallback are ignored and CPython raises TypeError.
from typing import Callable, reveal_type


class Bag:
    def __init__(self) -> None:
        self.__len__ = lambda: 99
        self.items = [1, 2]

    def __getattr__(self, name: str) -> Callable[..., str]:
        return lambda *args: name


def measure(b: Bag) -> int:
    try:
        return len(b)  # expect-error: Bag has no __len__
    except TypeError:
        return -1


def first(b: Bag) -> str:
    try:
        return str(next(iter(b)))  # expect-error: Bag is not iterable
    except TypeError:
        return 'not iterable'


bag = Bag()
reveal_type(bag.items)
reveal_type(bag.__len__)
size = measure(bag)
reveal_type(size)
label = first(bag)
reveal_type(label)
